const tr=(th,en)=>state.lang==='th'?th:en;
const fmt=(n,d=2)=>Number(n).toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d});
const quoteAmount=n=>{const a=Math.abs(Number(n));return fmt(n,a>0&&a<1?Math.min(8,Math.max(2,Math.ceil(-Math.log10(a))+2)):2);};
const number=n=>Number(n).toLocaleString('en-US',{maximumFractionDigits:2});
const price=(n,symbol=identity().symbol,provider=identity().provider)=>{const absolute=Math.abs(Number(n)),fallback=absolute>0&&absolute<1?Math.min(12,Math.max(5,Math.ceil(-Math.log10(absolute))+3)):absolute<3?5:absolute<1000?3:2;const digits=provider==='binance'?pricePrecision(cryptoMarket(symbol)?.tickSize,fallback):provider==='broker'?pricePrecision(broker.market(symbol)?.tickSize,fallback):fallback;return Number(n).toLocaleString('en-US',{minimumFractionDigits:digits,maximumFractionDigits:digits});};
const stamp=time=>new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Bangkok',month:'short',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(time);
const current=()=>workspace?.chart;
const frameKey=tf=>/^(?:\d+)?M$/.test(String(tf))?'month:'+tf:timeframeMs(tf);
function identity(chart=current()) {const market=chart?.market||{};const symbol=market.symbol||'binance:BTCUSDT',parts=symbol.split(':'),prefix=parts.length>1?parts[0].toLowerCase():'binance',provider=prefix.startsWith('broker_')?'broker':prefix,full=prefix+':'+parts.at(-1),timeframe=market.timeframe||'15';return {symbol:parts.at(-1),provider,timeframe,key:full+'|'+frameKey(timeframe),full};}
function cryptoMarket(symbol){try{return binance.market(symbol);}catch{return undefined;}}
function currency(symbol=identity().symbol,provider=identity().provider){if(provider==='binance')return cryptoMarket(symbol)?.quoteAsset||'—';if(provider==='broker')return broker.market(symbol)?.currency||'—';return symbol.endsWith('JPY')?'JPY':symbol.endsWith('USDT')?'USDT':'USD';}
function displayTF(tf){return /^\d+$/.test(tf)?Number(tf)>=60?Number(tf)%60===0?Number(tf)/60+'h':tf+'m':tf+'m':tf;}
function save(){clearTimeout(persistTimer);persistTimer=setTimeout(()=>{try{localStorage.setItem(STORE,JSON.stringify(state));}catch{toast(tr('พื้นที่บันทึกเต็ม กรุณา Backup แล้วลดข้อมูล CSV','Storage is full. Export a backup and reduce imported data.'),true);}},200);}
function toast(text,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=text;$('toasts').append(el);setTimeout(()=>el.remove(),6500);}
function notice(text=''){$('market-notice').textContent=text;$('market-notice').hidden=!text;}
function download(name,content,type='text/plain'){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function applyLanguage(){document.documentElement.lang=state.lang;$('lang-btn').textContent=state.lang.toUpperCase();all('[data-i18n]').forEach(el=>{const key=el.dataset.i18n;el.innerHTML=state.lang==='en'?(EN[key]||thaiText.get(key)):thaiText.get(key);});$('asset-search').placeholder=tr('ค้นหาคู่เทรด เช่น BTC, ETH/BTC, THB','Search pairs, e.g. BTC, ETH/BTC, THB');$('watch-search').placeholder=tr('ค้นหาใน Watchlist','Search watchlist');$('prompt').placeholder=tr('เช่น EMA 21/50 เสี่ยง 0.5% RR 1:2','e.g. EMA 21/50 risk 0.5% RR 1:2');updateRecipe();if(ready){renderAssetCatalog();connections?.refreshLanguage();renderWatchlist();}save();}
function updateRecipe(){const c=state.config;$('recipe-title').textContent=TITLES[c.kind];const description=c.kind==='trend'?tr(`EMA ${c.fast} ตัด EMA ${c.slow} เมื่อปิดแท่ง เข้าเปิดแท่งถัดไป`, `EMA ${c.fast}/${c.slow} cross at bar close. Enter at next open.`):c.kind==='mean'?tr(`ราคาปิดกลับเข้า BB (${c.period}, ${c.deviation}σ) หลังปิดนอกกรอบ`, `Close re-enters BB (${c.period}, ${c.deviation}σ) after a close outside.`):tr(`ราคาปิดทะลุ High/Low ของ ${c.period} แท่งก่อนหน้า`, `Close breaks the high/low of the previous ${c.period} bars.`);$('recipe-description').textContent=description;$('strategy-explainer').textContent=description+tr(` SL = ATR(${c.atrPeriod}) × ${c.stopATR} • TP = ${c.reward}R`, ` SL = ATR(${c.atrPeriod}) × ${c.stopATR}. TP = ${c.reward}R.`);$('recipe-risk').textContent=c.risk+'% risk';$('recipe-rr').textContent='1 : '+c.reward+' R';$('recipe-editor').value=JSON.stringify(c,null,2);}
function addMessage(text,user=false,labelText='NS RESEARCH · LOCAL RULES'){const item=document.createElement('div');item.className='message '+(user?'user':'assistant');if(!user){const label=document.createElement('span');label.className='message-label';label.textContent=labelText;item.append(label);}item.append(document.createTextNode(text));$('messages').append(item);while($('messages').children.length>8)$('messages').firstElementChild.remove();$('research-scroll').scrollTop=$('research-scroll').scrollHeight;}
async function promptStrategy(text){text=text.trim();if(!text)return;addMessage(text,true);if(aiModel){await requestAI(text);return;}const recipe=recipeFromText(text,state.config);if(recipe.indicator){current()?.addNativeIndicator(recipe.indicator);addMessage(tr(`เพิ่ม ${recipe.indicator.toUpperCase()} บนกราฟแล้ว`, `Added ${recipe.indicator.toUpperCase()} to the chart.`));}if(recipe.recognized){try{state.config=validateConfig(recipe.config);updateRecipe();syncRecipeIndicators();save();addMessage(tr(`ตั้งค่า ${TITLES[state.config.kind]} แล้ว ตรวจสอบกฎด้านล่างและกด Run backtest ได้เลย`, `Configured ${TITLES[state.config.kind]}. Review the rules, then run a backtest.`));}catch(e){addMessage(e.message);}}else if(!recipe.indicator)addMessage(tr('รองรับคีย์เวิร์ด Trend / EMA, Mean Reversion / BB, Breakout, risk และ RR เท่านั้น ตัวอย่าง: EMA 21/50 risk 0.5% RR 1:2','Supported keywords: Trend / EMA, Mean Reversion / BB, Breakout, risk and RR. Example: EMA 21/50 risk 0.5% RR 1:2.'));}

function capture(provider,ticker,tf,bars){const prefix=provider==='broker'?(broker.providerName||'broker'):provider;const key=prefix+':'+ticker+'|'+frameKey(tf);const existing=history.get(key)||[];const merged=new Map(existing.map(b=>[b.time,b]));bars.forEach(b=>merged.set(b.time,b));const ordered=[...merged.values()].sort((a,b)=>a.time-b.time).slice(-10000);history.set(key,ordered);if(ordered.length)lastBars.set(prefix+':'+ticker,ordered.at(-1));if(ready&&identity().key===key)refreshMarket(false);}
const csv=new CSVProvider(capture,state.imports);
const binance=new BinanceMarketProvider({onBars:capture,onCatalog:()=>{renderAssetCatalog();if(ready)refreshMarket(false);},onStatus:status=>{if(ready&&identity().provider==='binance'&&status.symbol===identity().symbol&&frameKey(status.timeframe)===frameKey(identity().timeframe))refreshConnection();}});
const broker=new BrokerMarketProvider({onBars:capture,onStatus:()=>{if(ready&&identity().provider==='broker')refreshConnection();}});
function clearBrokerHistory(){for(const key of history.keys())if(/^broker(?:_|:)/.test(key))history.delete(key);for(const key of lastBars.keys())if(/^broker(?:_|:)/.test(key))lastBars.delete(key);}
async function brokerConnected(profile){
 clearBrokerHistory();broker.providerName='broker_'+profile.id;broker.profileLabel=profile.label;
 current().data.registerProvider(broker.providerName,broker);
 const candidates=broker.catalog.filter(m=>profile.kind==='all'||m.assetClass===profile.kind),selected=candidates.find(m=>/^XAUUSD(?:[._-]|$)/i.test(m.ticker))||candidates[0];if(!selected){connections.renderBroker();notice(tr('เชื่อมบัญชีแล้ว แต่ไม่มีสัญญาที่ตรงกับตลาดที่เลือก ตรวจรายการใน Terminal','Account connected, but it has no contracts matching the selected market. Check the terminal catalog'));return;}
 connections.renderBroker();const full=broker.providerName+':'+selected.ticker;
 if(!state.watchlist.includes(full))state.watchlist.push(full);save();await activateSymbol(full);
 toast(tr('เชื่อมบัญชีแล้ว: ','Account connected: ')+profile.label+' · '+broker.connection.platform);
}
async function disconnectBroker(){
 const previous=broker.providerName;broker.disconnect();clearBrokerHistory();
 for(const cell of workspace.cells())if(identity(cell.chart).provider==='broker')await cell.chart.setMarket({symbol:'binance:BTCUSDT',timeframe:'15',bars:720});
 if(previous)current().data.unregisterProvider(previous);broker.providerName=null;refreshMarket(true);
}
function refreshBrokerConnection(){
 const id=identity(),status=broker.status(id.symbol,id.timeframe),replay=!!current().replay.state.active;
 const live=status.type==='live'&&Date.now()-status.tickAt<=30000&&Date.now()-status.updatedAt<=30000;
 const label=replay?'BROKER · REPLAY':live?'BROKER · LIVE':status.type==='stale'?'BROKER · STALE':status.type==='error'?'BROKER · ERROR':'BROKER · WAIT';
 $('source-label').textContent=label;const color=live?'var(--up)':status.type==='error'?'var(--down)':'#d6b776';$('source-label').style.color=$('source-dot').style.background=color;
 const clock=status.tickAt?new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Bangkok',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(status.tickAt):'—';
 $('source-detail').textContent=(broker.profileLabel||broker.connection?.broker||'Broker')+' · Tick '+clock+' TH · 2s'+(status.bid?' · '+price(status.bid)+' / '+price(status.ask):'');
 $('instrument-source').textContent=replay?'REPLAY':live?'LIVE':'BROKER';$('instrument-name').textContent=broker.market(id.symbol)?.description||id.symbol;
 $('broker-pair').value=id.symbol;$('paper-buy').disabled=$('paper-sell').disabled=true;
 if(status.type==='error')notice(status.error||tr('รอข้อมูลจาก terminal โบรกเกอร์','Waiting for broker terminal data'));
 else if(status.type==='stale')notice(tr('ไม่มี tick สด ข้อมูลอาจอยู่นอกเวลาตลาดหรือ terminal ขาดการเชื่อมต่อ','No fresh tick. The market may be closed or the terminal disconnected'));
 else if(live)notice();
}
function renderAssetCatalog(){const catalog=binance.catalogState(),markets=catalog.markets,pair=$('crypto-pair');$('crypto-market-count').textContent=markets.length?'('+number(markets.length)+')':'…';if(markets.length&&pairCatalogAt!==catalog.revision){const selected=identity().provider==='binance'?identity().symbol:pair.value,groups=new Map();for(const market of markets){if(!groups.has(market.quoteAsset))groups.set(market.quoteAsset,[]);groups.get(market.quoteAsset).push(market);}const quotes=[...groups.keys()].sort();pair.innerHTML=quotes.map(quote=>`<optgroup label="${escape(quote)}">${groups.get(quote).map(m=>`<option value="${escape(m.ticker)}">${escape(m.baseAsset)} / ${escape(m.quoteAsset)}</option>`).join('')}</optgroup>`).join('');if([...pair.options].some(o=>o.value===selected))pair.value=selected;const filter=$('asset-quote'),selectedQuote=filter.value;filter.innerHTML=`<option value="">${tr('ทุกสกุลเงิน','All quote currencies')}</option>`+quotes.map(quote=>`<option value="${escape(quote)}">${escape(quote)}</option>`).join('');if(quotes.includes(selectedQuote))filter.value=selectedQuote;pairCatalogAt=catalog.revision;}renderAssetRows();}
function renderAssetRows(){const catalog=binance.catalogState(),filtered=filterSpotMarkets(catalog.markets,$('asset-search').value,$('asset-quote').value),pages=Math.max(1,Math.ceil(filtered.length/100));assetPage=Math.max(0,Math.min(assetPage,pages-1));const rows=filtered.slice(assetPage*100,assetPage*100+100);$('asset-refresh').disabled=catalog.loading;const bases=new Set(catalog.markets.map(m=>m.baseAsset)).size;const updated=catalog.updatedAt?stamp(catalog.updatedAt)+' TH':'—';$('asset-summary').textContent=catalog.loading?tr('กำลังโหลดคู่เทรดจาก Binance…','Loading all Binance Spot markets…'):tr(`${number(filtered.length)} / ${number(catalog.markets.length)} คู่ · ${number(bases)} สินทรัพย์ · อัปเดต ${updated}`,`${number(filtered.length)} / ${number(catalog.markets.length)} pairs · ${number(bases)} assets · Updated ${updated}`);$('asset-error').textContent=catalog.error?catalog.error+(catalog.markets.length?tr(' · กำลังแสดงรายการที่โหลดไว้ก่อนหน้า',' · Showing the previously loaded catalog'):''):'';$('asset-rows').innerHTML=rows.length?rows.map(m=>{const favorite=state.watchlist.includes('binance:'+m.ticker);return `<tr><td><button class="asset-open" data-open-market="${escape(m.ticker)}"><strong>${escape(m.baseAsset)} <span>/ ${escape(m.quoteAsset)}</span></strong><small>${escape(m.ticker)}</small></button></td><td>${escape(m.baseAsset)}</td><td>${escape(m.quoteAsset)}</td><td><button class="square ${favorite?'favorite':''}" data-star-market="${escape(m.ticker)}" aria-label="${favorite?'Remove from':'Add to'} watchlist">${favorite?'★':'☆'}</button><button class="primary asset-chart-button" data-open-market="${escape(m.ticker)}">${tr('เปิดกราฟ','Open chart')} ↗</button></td></tr>`;}).join(''):`<tr><td colspan="4" class="empty">${catalog.loading?tr('กำลังโหลด…','Loading…'):tr('ไม่พบคู่เทรด ลองเปลี่ยนคำค้นหาหรือตัวกรอง','No matching pairs. Change your search or quote filter.')}</td></tr>`;$('asset-page').textContent=`${assetPage+1} / ${pages}`;$('asset-prev').disabled=assetPage===0;$('asset-next').disabled=assetPage>=pages-1;}
async function loadAssetCatalog(force=false){try{await binance.listSymbols({force});if(force&&workspace)workspace.chart.data.registerProvider('binance',binance);}catch{}renderAssetCatalog();}
function refreshConnection(){if(!workspace)return;const id=identity(),crypto=id.provider==='binance',replay=!!current().replay.state.active;$('crypto-controls').hidden=!crypto;document.body.classList.toggle('crypto-mode',crypto);$('broker-controls').hidden=id.provider!=='broker';if(id.provider==='broker'){refreshBrokerConnection();return;}if(!crypto){$('paper-buy').disabled=$('paper-sell').disabled=!latestBar();return;}const pair=$('crypto-pair');if(![...pair.options].some(o=>o.value===id.symbol)){const option=document.createElement('option');option.value=option.textContent=id.symbol;pair.append(option);}pair.value=id.symbol;const status=binance.status(id.symbol,id.timeframe),age=status.updatedAt?Date.now()-status.updatedAt:Infinity,fresh=age<25000;const live=status.type==='live'&&fresh,polling=status.type==='polling'&&fresh;const label=replay?'BAR REPLAY':live?'BINANCE · LIVE':polling?'BINANCE · REST':status.type==='error'?'BINANCE · ERROR':status.type==='closed'?'BINANCE · OFFLINE':'BINANCE · CONNECTING';$('source-label').textContent=label;const color=live||polling?'var(--up)':status.type==='error'?'var(--down)':'#d6b776';$('source-label').style.color=$('source-dot').style.background=color;const clock=status.updatedAt?new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Bangkok',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(status.updatedAt):'—';$('source-detail').textContent=replay?tr('ข้อมูลย้อนหลัง · Replay','Historical replay'):tr('อัปเดต ','Updated ')+clock+' TH · '+(polling?'REST / 5s':status.transport||'WebSocket')+(!fresh&&status.updatedAt?tr(' · ข้อมูลเก่า',' · stale'):'');$('instrument-source').textContent=replay?'REPLAY':live?'LIVE':polling?'REST':'WAIT';$('paper-buy').disabled=$('paper-sell').disabled=(!replay&&!live&&!polling)||!cryptoMarket(id.symbol)?.quoteAsset;if(status.type==='error')notice(status.error||tr('เชื่อมต่อ Binance ไม่สำเร็จ กดเชื่อมต่อใหม่','Cannot connect to Binance. Press Reconnect.'));else if(status.type==='reconnecting'&&!replay)notice(tr('สัญญาณ WebSocket ขาด กำลังรับข้อมูล REST และเชื่อมต่อใหม่…','WebSocket interrupted. Using REST updates and reconnecting…'));else if(['live','polling'].includes(status.type))notice();}
function syncRecipeIndicators(){const chart=current();if(!chart)return;const c=state.config;if(c.kind==='mean'){const handle=chart.indicators().find(h=>h.nativeType==='bollinger-bands');if(handle)handle.setInputs({length:c.period,mult:c.deviation});else chart.addNativeIndicator('bollinger-bands',{inputs:{length:c.period,mult:c.deviation}});}else if(c.kind==='trend'){const handles=chart.indicators().filter(h=>h.nativeType==='ema');for(const [i,length]of[c.fast,c.slow].entries())if(handles[i])handles[i].setInput('length',length);else chart.addNativeIndicator('ema',{inputs:{length}});}}
async function connectAI(){try{const response=await fetch(new URL('api/status',document.baseURI));if(!response.ok)throw new Error('AI adapter unavailable on this host');const result=await response.json();if(!result.ai)throw new Error('AI model is not configured on the local server');aiModel=result.model;const note=document.querySelector('[data-i18n="localNote"]');note.removeAttribute('data-i18n');note.textContent=tr('ตั้งค่าโมเดลไว้: ','Configured model: ')+aiModel+tr(' • ตรวจข้อเสนอก่อนกดทดสอบ',' · Review proposals before testing');const tag=document.querySelector('.panel-heading .small-tag');tag.textContent='AI CONFIGURED';const engine=document.querySelector('[data-i18n="localEngine"]');engine.removeAttribute('data-i18n');engine.textContent=aiModel;}catch(error){toast(error.message+' · Using local rules.',true);}}
async function requestAI(message){const button=document.querySelector('.send-btn');button.disabled=true;try{const response=await fetch(new URL('api/research',document.baseURI),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message,config:state.config}),signal:AbortSignal.timeout(65000)});const result=await response.json();if(!response.ok)throw new Error(result.error||'AI request failed');state.config=validateConfig(result.config);updateRecipe();syncRecipeIndicators();save();addMessage(result.explanation,false,'NS RESEARCH · '+aiModel);}catch(error){addMessage(error.message,false,'NS RESEARCH · AI ERROR');}finally{button.disabled=false;}}
function barsForChart(){const id=identity(),bars=history.get(id.key)||[],replay=current()?.replay?.state;let visible=replay?.active?bars.filter(b=>b.time<=replay.cursorTime):bars;if(['binance','broker'].includes(id.provider)&&!replay?.active)visible=visible.filter(b=>b.time+timeframeMs(id.timeframe)<=Date.now());return visible;}
function latestBar(){const id=identity(),bars=history.get(id.key)||[],replay=current()?.replay?.state;return replay?.active?bars.filter(b=>b.time<=replay.cursorTime).at(-1):bars.at(-1);}
function getDrawKey(chart){const id=identity(chart);return id.full;}
function storeDrawings(chart){try{state.drawings[getDrawKey(chart)]=chart.drawings.toJSON();save();}catch{}}
function bindChart(chart){if(chartBindings.has(chart))return;chartBindings.add(chart);styleTerminalChart(chart,state.theme);let previous=getDrawKey(chart);chart.on('market:changed',()=>{const next=getDrawKey(chart);if(next!==previous){chart.drawings.fromJSON(state.drawings[next]||{version:1,drawings:[]});previous=next;}refreshMarket(true);});chart.on('bar',bar=>{const id=identity(chart),arr=history.get(id.key)||[];const existing=arr.findIndex(b=>b.time===bar.time);if(existing>=0)arr[existing]=bar;else{arr.push(bar);arr.sort((a,b)=>a.time-b.time);}history.set(id.key,arr.slice(-10000));lastBars.set(id.full,bar);processPaper(id,bar,!!chart.replay.state.active);processAlerts(id,bar);if(chart===current())refreshMarket(false);});for(const event of ['drawing:created','drawing:edited','drawing:removed'])chart.on(event,()=>storeDrawings(chart));for(const event of ['replay:start','replay:step','replay:end'])chart.on(event,()=>{if(chart===current())refreshMarket(false);});chart.on('load:end',e=>{if(chart===current()){if(e.bars===0)notice(tr('ไม่มีข้อมูลจากแหล่งที่เลือก ตรวจการเชื่อมต่อหรือนำเข้า CSV ของคุณ','No data received. Check the connection or import your own CSV.'));refreshMarket(true);}});chart.on('error',e=>{if(chart===current())notice(String(e?.error?.message||e?.message||e?.error||'Data provider error'));});}

function refreshMarket(resetFields=false){if(!workspace)return;const id=identity(),meta=id.provider==='binance'?cryptoMarket(id.symbol):id.provider==='broker'?broker.market(id.symbol):null,isImported=!!state.imports[id.symbol],isCrypto=id.provider==='binance',replay=current()?.replay?.state?.active;
 if(id.key!==lastIdentity){resetFields=true;lastIdentity=id.key;}
 $('source-select').value=isCrypto?'binance':id.provider==='broker'?'broker':'csv';$('source-label').textContent=replay?'BAR REPLAY':isCrypto?'BINANCE DATA':isImported?'IMPORTED CSV':'WAITING FOR DATA';$('source-label').style.color=isCrypto?'var(--up)':'#c9b87e';$('source-dot').style.background=isCrypto?'var(--up)':'#d6b776';$('source-detail').textContent=isCrypto?'External crypto feed · '+id.symbol:isImported?'Offline · '+id.symbol:'Waiting for external feed';$('instrument-source').textContent=isCrypto?'BINANCE':isImported?'CSV':'WAIT';$('instrument-symbol').textContent=id.symbol;$('instrument-name').textContent=meta?.description||(isCrypto?'Binance Spot':'Imported market data');$('instrument-badge').textContent=meta?.badge||id.symbol.slice(0,2);$('instrument-badge').style.color=meta?.color||'var(--accent)';
 $('workspace-symbol').textContent=id.symbol;$('workspace-timeframe').textContent=displayTF(id.timeframe);$('instrument-currency').textContent=currency();
 const bar=latestBar(),bars=history.get(id.key)||[];
 if(bar){const previous=bars.findLast(b=>b.time<bar.time),change=previous?bar.close-previous.close:bar.close-bar.open,pct=previous?change/previous.close*100:change/bar.open*100;$('instrument-price').textContent=price(bar.close);$('instrument-change').textContent=(change>=0?'+':'')+price(change)+' ('+(pct>=0?'+':'')+fmt(pct)+'%) · bar';$('instrument-change').className=change>=0?'up':'down';$('ohlc-detail').innerHTML=['open','high','low','close'].map(k=>`<div><span>${k.toUpperCase()}</span>${price(bar[k])}</div>`).join('');if(resetFields){$('risk-entry').value=bar.close.toFixed(bar.close<3?5:3);const v=atr(bars,14).at(-1)||bar.close*.003;$('risk-stop').value=Math.max(.00001,bar.close-v*1.5).toFixed(bar.close<3?5:3);$('order-stop').value='';$('order-target').value='';$('order-units').value=id.symbol==='BTCUSDT'?'0.01':'1';}if(isCrypto)$('source-detail').textContent='Last bar '+new Date(bar.time).toISOString().slice(11,19)+' UTC · external feed';}
 else{$('instrument-price').textContent='—';$('instrument-change').textContent=tr('กำลังโหลดข้อมูล…','Loading bars…');}
 renderWatchlist();calculateRisk();renderPaper();refreshConnection();tradingUI?.sync();
 if(lastResult&&resultIdentity?.key!==id.key)$('results-title').textContent=TITLES[lastResult.config.kind]+' · '+resultIdentity.symbol+' · '+displayTF(resultIdentity.timeframe)+' (previous chart)';
 if(!hasInitialResult&&bar&&barsForChart().length>60){hasInitialResult=true;runBacktest(false);}
}

function renderWatchlist(){
 const id=identity(),query=$('watch-search').value.trim().toLowerCase();
 const eligible=state.watchlist.filter(full=>!/^broker(?:_|:)/.test(full)||broker.connection&&full.startsWith(broker.providerName+':'));
 const rows=eligible.filter(full=>{const ticker=full.split(':').at(-1),meta=full.startsWith('binance:')?cryptoMarket(ticker):full.startsWith('broker_')?broker.market(ticker):null;return(ticker+' '+(meta?.description||'')+' '+full).toLowerCase().includes(query);});
 $('watch-count').textContent=query?rows.length+' / '+eligible.length:eligible.length;
 $('watchlist').innerHTML=rows.length?rows.map(full=>{const ticker=full.split(':').at(-1),prefix=full.split(':')[0],provider=prefix.startsWith('broker_')?'broker':prefix,meta=provider==='binance'?cryptoMarket(ticker):provider==='broker'?broker.market(ticker):null,bar=lastBars.get(full),change=bar?(bar.close/bar.open-1)*100:null,source=provider==='binance'?'Binance · Spot':provider==='broker'?(broker.connection?.broker||'Broker')+' · '+(meta?.assetClass==='futures'?'Futures':'Broker'):'CSV · Offline';return `<button class="watch-row ${id.full===full?'current':''}" data-symbol="${escape(full)}" title="${escape(ticker+' · '+source)}"><span class="asset-badge">${escape(meta?.badge||ticker.slice(0,2))}</span><span class="watch-symbol">${escape(ticker)}<small>${escape(source)}</small></span><span class="watch-price">${bar?price(bar.close,ticker,provider):'—'}</span><span class="watch-change ${change==null?'muted':change>=0?'up':'down'}">${change==null?'—':(change>=0?'+':'')+fmt(change)+'%'}</span></button>`;}).join(''):`<div class="empty">${tr('ไม่พบสินทรัพย์ในรายการ','No matching symbols')}</div>`;
}
async function activateSymbol(full){try{notice();if(/^broker(?:_|:)/.test(full)&&!broker.connection){connections.openBroker();return;}if(full.startsWith('broker:'))full=broker.providerName+':'+full.slice(7);if(/^broker_/.test(full)&&!full.startsWith(broker.providerName+':')){connections.openBroker();return;}if(full.startsWith('binance:'))ensureBinance();storeDrawings(current());await current().setMarket({symbol:full,timeframe:identity().timeframe,bars:720});refreshMarket(true);}catch(e){notice(tr('โหลดข้อมูลไม่ได้: ','Data unavailable: ')+e.message);}}
function ensureBinance(){return binance;}
async function reconnectBinance(){const id=identity();if(id.provider!=='binance')return;const button=$('crypto-reconnect');button.disabled=true;try{binance.stop(id.symbol,id.timeframe);notice(tr('กำลังโหลดแท่งและเชื่อมต่อ Binance ใหม่…','Reloading candles and reconnecting to Binance…'));const depth=current().market.bars||720;await current().setMarket({symbol:id.full,timeframe:id.timeframe,bars:depth===720?721:720});refreshMarket(true);}catch(error){notice(error.message);}finally{button.disabled=false;}}

async function runBacktest(showToast=true){const keepCollapsed=!showToast&&$('analysis-panel').classList.contains('collapsed');const button=$('run-btn');button.disabled=true;try{await new Promise(r=>setTimeout(r,0));const bars=barsForChart();lastResult=backtest(bars,state.config);resultIdentity={...identity()};renderResults();if(showToast)toast(tr(`ทดสอบ ${bars.length} แท่ง · ${lastResult.trades.length} เทรด เรียบร้อย`,`Tested ${bars.length} bars · ${lastResult.trades.length} trades`));showTab('performance');if(keepCollapsed){$('analysis-panel').classList.add('collapsed');responsive?.syncAnalysis();}}catch(e){toast(e.message,true);}finally{button.disabled=false;}}
function renderResults(){const r=lastResult;if(!r)return;const c=r.config;$('trade-count').textContent=r.trades.length;$('results-title').textContent=TITLES[c.kind]+' · '+resultIdentity.symbol+' · '+displayTF(resultIdentity.timeframe);$('result-source').textContent=resultIdentity.provider==='binance'?'BINANCE':resultIdentity.provider==='broker'?'BROKER':'CSV';const sign=r.net>=0?'+':'';$('metrics').innerHTML=`<div class="metric"><span>NET PROFIT</span><strong class="${r.net>=0?'up':'down'}">${sign+quoteAmount(r.net)}</strong><small>${sign+fmt(r.netPct)}% · ${currency(resultIdentity.symbol,resultIdentity.provider)} units</small></div><div class="metric"><span>WIN RATE</span><strong>${fmt(r.winRate,1)}<span style="font-size:12px">%</span></strong><small>${r.trades.filter(t=>t.pnl>0).length} wins / ${r.trades.length} trades</small></div><div class="metric"><span>PROFIT FACTOR</span><strong>${r.profitFactor===Infinity?'∞':r.profitFactor==null?'—':fmt(r.profitFactor)}</strong><small>Net winning / losing P&L</small></div><div class="metric"><span>MAX DRAWDOWN</span><strong>${fmt(r.maxDrawdownPct)}<span style="font-size:12px">%</span></strong><small>${quoteAmount(r.maxDrawdown)} · bar-close equity</small></div><div class="metric"><span>TRADES</span><strong>${r.trades.length}</strong><small>closed</small></div>`;
 const values=r.equity.map(p=>p.value),min=Math.min(...values),max=Math.max(...values),range=max-min||1,points=r.equity.map((p,i)=>`${i/(r.equity.length-1)*900},${69-(p.value-min)/range*54}`).join(' '),color=r.net>=0?'var(--up)':'var(--down)';$('equity-chart').innerHTML=`<defs><linearGradient id="eq-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="${color}" stop-opacity=".18"/><stop offset="100%" stop-color="${color}" stop-opacity="0"/></linearGradient></defs><path d="M0 74 L${points.split(' ').join(' L')} L900 78 L0 78 Z" fill="url(#eq-fill)"/><line x1="0" y1="70" x2="900" y2="70" stroke="var(--border)" stroke-width=".5"/><polyline points="${points}" fill="none" stroke="${color}" stroke-width="1.5" vector-effect="non-scaling-stroke"/>`;$('equity-end').textContent=number(values.at(-1));$('result-footnote').textContent=`${r.bars} bars · ${stamp(r.from)} – ${stamp(r.to)} TH · Next-open entries · ${c.feeBps} bp fee + ${c.slippageBps} bp slippage / side · SL first · no margin model`;
 $('trade-rows').innerHTML=r.trades.length?r.trades.slice().reverse().map(t=>`<tr><td>${stamp(t.entryTime)}</td><td class="${t.side===1?'up':'down'}">${t.side===1?'LONG':'SHORT'}</td><td>${price(t.entry,resultIdentity.symbol,resultIdentity.provider)}</td><td>${price(t.exit,resultIdentity.symbol,resultIdentity.provider)}</td><td class="${t.pnl>=0?'up':'down'}">${t.pnl>=0?'+':''}${quoteAmount(t.pnl)}</td><td>${fmt(t.r)}R</td><td>${escape(t.reason)}</td></tr>`).join(''):'<tr><td colspan="7" class="empty">No signals for these rules and this data range.</td></tr>';
 const chart=current();try{chart.marks.set(r.trades.flatMap((t,i)=>[{id:'bt-in-'+i,time:t.entryTime,glyph:{shape:'circle',color:t.side===1?'#50c4a5':'#ee7c87',letter:t.side===1?'B':'S'},title:(t.side===1?'LONG':'SHORT')+' · '+price(t.entry,resultIdentity.symbol,resultIdentity.provider),content:{text:'Backtest entry: '+stamp(t.entryTime)+' TH'},group:'backtest'}]));}catch{}
}
function showTab(tab){responsive?.closePanel();activeTab=tab;document.body.classList.toggle('journal-view',tab==='journal');$('analysis-panel').classList.remove('collapsed');all('[data-tab]').forEach(el=>{const active=el.dataset.tab===tab;el.classList.toggle('active',active);el.setAttribute('aria-selected',String(active));});all('.tab-content').forEach(el=>el.hidden=el.id!=='tab-'+tab);all('[data-view]').forEach(el=>el.classList.toggle('selected',el.dataset.view===tab));if(tab==='recipe')updateRecipe();if(tab==='paper'){marketTools?.select('paper');renderPaper();}if(tab==='journal'){renderJournal();ledgerUI?.open();journalDashboard?.open();}responsive?.syncAnalysis();}
function calculateRisk(){try{const value=positionSize(...['risk-balance','risk-pct','risk-entry','risk-stop','risk-tick-size','risk-tick-value','risk-lot-step'].map(id=>Number($(id).value)));$('risk-result').innerHTML=`<span>Risk $${fmt(value.actualRisk)} / $${fmt(value.risk)}</span><strong>${number(value.lots)} lots</strong>`;}catch{$('risk-result').textContent=tr('กรอกข้อมูลราคาและสเปก Tick ให้ครบ','Enter prices and tick specifications');}}

function balanceFor(cur){return Number(state.balances[cur]??(cur==='JPY'?1000000:10000));}
function placePaper(side){if(identity().provider==='broker')return toast(tr('ราคาโบรกพร้อมสำหรับกราฟและ Backtest; Paper CFD ยังไม่เปิดใช้','Broker prices are available for charts and backtests; CFD paper trading is not enabled'));const id=identity(),bar=latestBar(),units=Number($('order-units').value),stop=$('order-stop').value?Number($('order-stop').value):null,target=$('order-target').value?Number($('order-target').value):null;if(!bar||!Number.isFinite(units)||units<=0||units>1e9)return toast(tr('กรอกจำนวนหน่วยให้ถูกต้อง','Enter a valid number of asset units'),true);if(stop!==null&&(!Number.isFinite(stop)||stop<=0||(stop-bar.close)*side>=0)||target!==null&&(!Number.isFinite(target)||target<=0||(target-bar.close)*side<=0))return toast(tr('SL/TP ต้องอยู่ด้านที่ถูกต้องของ BUY หรือ SELL','SL/TP must be on the correct side of the entry'),true);const cur=currency(id.symbol),fee=bar.close*units*state.config.feeBps/10000;if(fee>=balanceFor(cur))return toast(tr('ค่าธรรมเนียมสูงกว่าเงินจำลองคงเหลือ','Fees exceed the simulated balance'),true);const replay=!!current().replay.state.active;state.balances[cur]=balanceFor(cur)-fee;state.positions.push({id:crypto.randomUUID(),symbol:id.symbol,full:id.full,timeframe:id.timeframe,side,units,entry:bar.close,stop,target,currency:cur,entryFee:fee,time:bar.time,feeBps:state.config.feeBps,replay});save();renderPaper();showTab('paper');toast(tr('เปิดสถานะจำลองแล้ว','Paper position opened'));}
function closePaper(id,exit,reason='Manual close'){const index=state.positions.findIndex(p=>p.id===id);if(index<0)return;const p=state.positions[index];if(exit==null&&p.full!==identity().full){activateSymbol(p.full);toast(tr('เลือกกราฟให้แล้ว กด Close อีกครั้งเมื่อราคาพร้อม','Chart selected. Press Close again once its price is available.'));return;}const bar=p.full===identity().full?latestBar():lastBars.get(p.full);exit=exit??bar?.close;if(!Number.isFinite(exit))return toast(tr('เปิดกราฟสินทรัพย์นี้เพื่อรับราคาปิด','Open this symbol to get an exit price'),true);const fee=exit*p.units*p.feeBps/10000,gross=(exit-p.entry)*p.side*p.units,pnl=gross-p.entryFee-fee;state.balances[p.currency]=balanceFor(p.currency)+gross-fee;state.closed.unshift({...p,exit,exitTime:bar?.time||Date.now(),pnl,reason});state.closed=state.closed.slice(0,500);state.positions.splice(index,1);save();renderPaper();}
function processPaper(id,bar,replayMode=false){for(const p of [...state.positions]){if(p.full!==id.full||p.timeframe!==id.timeframe||p.replay!==replayMode||bar.time<p.time)continue;const exit=resolveExit({...p,stop:p.stop??(p.side===1?-Infinity:Infinity),target:p.target??(p.side===1?Infinity:-Infinity)},bar.time===p.time?{open:bar.close,high:bar.close,low:bar.close}:bar);if(exit){closePaper(p.id,exit.price,exit.reason);toast('Paper '+p.symbol+' · '+exit.reason);}}}
function renderPaper(){const cur=currency();$('paper-balance').textContent=fmt(balanceFor(cur))+' '+cur;$('position-rows').innerHTML=state.positions.length?state.positions.map(p=>{const bar=p.full===identity().full?latestBar():lastBars.get(p.full),pnl=bar?(bar.close-p.entry)*p.side*p.units-p.entryFee:null;return `<tr><td>${escape(p.symbol)}<small class="muted"> · ${p.replay?'Replay':p.full.startsWith('csv:')?'CSV · Offline':'Binance'}</small></td><td class="${p.side===1?'up':'down'}">${p.side===1?'BUY':'SELL'}</td><td>${number(p.units)}</td><td>${price(p.entry,p.symbol,p.full.split(':')[0])}</td><td>${p.stop?price(p.stop,p.symbol,p.full.split(':')[0]):'—'} / ${p.target?price(p.target,p.symbol,p.full.split(':')[0]):'—'}</td><td class="${pnl>=0?'up':'down'}">${pnl==null?'—':quoteAmount(pnl)} ${escape(p.currency)}</td><td><button class="close-position" data-close-position="${escape(p.id)}">Close</button></td></tr>`;}).join(''):'<tr><td colspan="7" class="empty">No open positions. Use the paper order panel to practice.</td></tr>';$('paper-history').textContent=state.closed.length?'Recent closed · '+state.closed.slice(0,4).map(p=>p.symbol+' '+(p.pnl>=0?'+':'')+quoteAmount(p.pnl)+' '+p.currency+' ('+p.reason+')').join(' · '):'No closed paper positions.';}
function renderJournal(){$('journal-entries').innerHTML=state.notes.length?state.notes.map(n=>`<div class="journal-entry"><span class="stamp">${stamp(n.time)} TH<br>${escape(n.symbol)} · ${escape(n.setup)}</span><p>${escape(n.text)}</p><button class="square" data-remove-note="${escape(n.id)}" aria-label="Delete note">×</button></div>`).join(''):`<div class="empty">${tr('บันทึกแผนและบทเรียนแรกของคุณได้เลย','Write your first plan or trading lesson.')}</div>`;}
function renderAlerts(){$('alert-count').textContent=state.alerts.filter(a=>!a.fired).length||'';$('alert-list').innerHTML=state.alerts.length?state.alerts.map(a=>`<div class="alert-row"><span>${escape(a.symbol)} ${a.condition==='above'?'≥':'≤'} ${price(a.price,a.symbol,a.full.split(':')[0])}<small>${a.fired?'Triggered':a.full.startsWith('csv:')?'CSV · Offline':/^broker_/.test(a.full)?'Broker · open page only':'Binance · open page only'}</small></span><button class="square" data-remove-alert="${escape(a.id)}" aria-label="Delete alert">×</button></div>`).join(''):'<div class="empty">No alerts yet.</div>';}
function processAlerts(id,bar){let changed=false;for(const alert of state.alerts){if(alert.full!==id.full||alert.fired)continue;if(alert.condition==='above'?bar.close>=alert.price:bar.close<=alert.price){alert.fired=true;changed=true;toast('Price alert · '+id.symbol+' '+price(bar.close));}}if(changed){save();renderAlerts();}}

async function importFile(file){$('import-error').textContent='';if(!file)return;if(file.size>25*1024*1024)throw new Error('Maximum file size: 25 MB');const text=await file.text();if(file.name.toLowerCase().endsWith('.json')){const backup=JSON.parse(text);if(backup?.type!=='ns-capital-backup'||backup.state?.version!==1)throw new Error('Not an NS Capital Terminal backup');const next=backup.state;next.config=validateConfig(next.config);for(const [key,value]of Object.entries(next.imports||{})){if(!/^[A-Z0-9._-]{1,24}$/.test(key))throw new Error('Invalid imported symbol');value.bars=validateBars(value.bars);}if(!Array.isArray(next.notes)||!Array.isArray(next.positions)||!Array.isArray(next.alerts)||!Array.isArray(next.closed)||!Array.isArray(next.watchlist))throw new Error('Invalid backup records');localStorage.setItem(STORE,JSON.stringify(removeSyntheticState({...defaults,...next})));if(backup.workspace)localStorage.setItem('ns-capital-charts',JSON.stringify(backup.workspace));location.reload();return;}
 const ticker=$('import-symbol').value.toUpperCase().replace(/[^A-Z0-9._-]/g,'').slice(0,24);if(!ticker)throw new Error('Enter a symbol name for your imported data');const offset=Number($('import-offset').value);if(!Number.isFinite(offset)||offset< -12||offset>14)throw new Error('UTC offset: -12 to +14');const bars=parseCSV(text,offset*60);const record=csv.addImport(ticker,bars);state.imports[ticker]=record;const full='csv:'+ticker;if(!state.watchlist.includes(full))state.watchlist.push(full);save();workspace.chart.data.registerProvider('csv',csv);const minutes=Math.max(1,Math.round(record.step/60000));await current().setMarket({symbol:full,timeframe:String(minutes),bars:720});$('import-dialog').close();refreshMarket(true);toast(tr(`นำเข้า ${number(bars.length)} แท่งเรียบร้อย`,`Imported ${number(bars.length)} bars`));}

function wireEvents(){
 $('crypto-browser').addEventListener('click',()=>{$('assets-dialog').showModal();renderAssetCatalog();void loadAssetCatalog();});$('asset-search').addEventListener('input',()=>{assetPage=0;renderAssetRows();});$('asset-quote').addEventListener('change',()=>{assetPage=0;renderAssetRows();});$('asset-refresh').addEventListener('click',()=>loadAssetCatalog(true));$('asset-prev').addEventListener('click',()=>{assetPage--;renderAssetRows();});$('asset-next').addEventListener('click',()=>{assetPage++;renderAssetRows();});$('asset-rows').addEventListener('click',async e=>{const open=e.target.closest('[data-open-market]'),star=e.target.closest('[data-star-market]');if(star){const full='binance:'+star.dataset.starMarket;if(state.watchlist.includes(full))state.watchlist=state.watchlist.filter(s=>s!==full);else state.watchlist.push(full);save();renderWatchlist();renderAssetRows();}else if(open){const full='binance:'+open.dataset.openMarket;if(!state.watchlist.includes(full))state.watchlist.push(full);save();$('assets-dialog').close();await activateSymbol(full);}});
 $('prompt-form').addEventListener('submit',e=>{e.preventDefault();promptStrategy($('prompt').value);$('prompt').value='';});$('prompt').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();$('prompt-form').requestSubmit();}});all('[data-prompt]').forEach(b=>b.addEventListener('click',()=>promptStrategy(b.dataset.prompt)));$('run-btn').addEventListener('click',()=>runBacktest());$('edit-recipe-btn').addEventListener('click',()=>showTab('recipe'));all('[data-tab]').forEach(b=>b.addEventListener('click',()=>showTab(b.dataset.tab)));all('[data-view]').forEach(b=>b.addEventListener('click',()=>showTab(b.dataset.view)));$('analysis-toggle').addEventListener('click',()=>$('analysis-panel').classList.toggle('collapsed'));
 $('apply-json').addEventListener('click',()=>{try{state.config=validateConfig(JSON.parse($('recipe-editor').value));updateRecipe();syncRecipeIndicators();save();runBacktest();}catch(e){toast(e.message,true);}});
 $('theme-btn').addEventListener('click',()=>{state.theme=state.theme==='dark'?'light':'dark';document.body.classList.toggle('light',state.theme==='light');styleTerminalWorkspace(workspace,state.theme);document.querySelector('meta[name=theme-color]').content=terminalTheme(state.theme).background;$('theme-btn').setAttribute('aria-pressed',String(state.theme==='light'));save();connections?.refreshTheme();});$('lang-btn').addEventListener('click',()=>{state.lang=state.lang==='th'?'en':'th';applyLanguage();tradingUI?.sync();ledgerUI?.render();journalDashboard?.render();pwa?.render();});$('focus-btn').addEventListener('click',()=>document.body.classList.toggle('focus'));
 $('watch-search').addEventListener('input',renderWatchlist);
 $('watchlist').addEventListener('click',e=>{const row=e.target.closest('[data-symbol]');if(row)activateSymbol(row.dataset.symbol);});$('watch-add').addEventListener('click',()=>{const id=identity();if(state.watchlist.includes(id.full))return toast(tr('สินทรัพย์นี้อยู่ใน Watchlist แล้ว','This symbol is already in your watchlist'));state.watchlist.push(id.full);save();renderWatchlist();});$('source-select').addEventListener('change',async e=>{if(e.target.value==='binance'){const id=identity();ensureBinance();const ticker=id.provider==='binance'?id.symbol:'BTCUSDT';const full='binance:'+ticker;if(!state.watchlist.includes(full))state.watchlist.push(full);save();notice(tr('กำลังเชื่อมต่อ Binance Spot…','Connecting to Binance Spot…'));await activateSymbol(full);}else if(e.target.value==='global'){connections.openGlobal();e.target.value=identity().provider;}else if(e.target.value==='broker'){if(broker.connection)await activateSymbol('broker:'+(broker.catalog.find(m=>/^XAUUSD/i.test(m.ticker))||broker.catalog[0]).ticker);else{connections.openBroker();e.target.value=identity().provider;}}else if(e.target.value==='csv'){const ticker=Object.keys(state.imports)[0];if(ticker)await activateSymbol('csv:'+ticker);else{$('import-dialog').showModal();e.target.value=identity().provider;}}});
 $('crypto-pair').addEventListener('change',async e=>{const full='binance:'+e.target.value;if(!state.watchlist.includes(full))state.watchlist.push(full);save();await activateSymbol(full);});$('crypto-reconnect').addEventListener('click',reconnectBinance);
 ['risk-balance','risk-pct','risk-entry','risk-stop','risk-tick-size','risk-tick-value','risk-lot-step'].forEach(id=>$(id).addEventListener('input',calculateRisk));$('paper-buy').addEventListener('click',()=>placePaper(1));$('paper-sell').addEventListener('click',()=>placePaper(-1));$('position-rows').addEventListener('click',e=>{const b=e.target.closest('[data-close-position]');if(b)closePaper(b.dataset.closePosition);});
 $('journal-form').addEventListener('submit',e=>{e.preventDefault();const text=$('journal-input').value.trim();if(!text)return;state.notes.unshift({id:crypto.randomUUID(),time:Date.now(),symbol:identity().symbol,setup:$('journal-setup').value,text});$('journal-input').value='';save();renderJournal();});$('journal-entries').addEventListener('click',e=>{const b=e.target.closest('[data-remove-note]');if(b){state.notes=state.notes.filter(n=>n.id!==b.dataset.removeNote);save();renderJournal();}});
 $('help-btn').addEventListener('click',()=>$('help-dialog').showModal());$('import-btn').addEventListener('click',()=>$('import-dialog').showModal());$('file-input').addEventListener('change',async e=>{try{await importFile(e.target.files[0]);}catch(error){$('import-error').textContent=error.message;}finally{e.target.value='';}});$('download-template').addEventListener('click',()=>download('NS-OHLCV-Template.csv','time,open,high,low,close,volume\n2026-10-01T00:00:00Z,2650,2653,2649,2652,100\n2026-10-01T00:15:00Z,2652,2655,2650,2654,120\n2026-10-01T00:30:00Z,2654,2656,2651,2652,105\n','text/csv'));
 $('backup-btn').addEventListener('click',()=>{if(current())storeDrawings(current());download('NS-Capital-Backup-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify({type:'ns-capital-backup',version:1,created:new Date().toISOString(),state,workspace:workspace.getState()},null,2),'application/json');toast(tr('ดาวน์โหลดไฟล์สำรองแล้ว','Backup downloaded'));});$('export-trades').addEventListener('click',()=>{if(!lastResult)return toast(tr('กรุณาทำ Backtest ก่อน','Run a backtest first'));const header='symbol,source,timeframe,entry_time,exit_time,side,entry,exit,units,pnl,R,reason';const rows=lastResult.trades.map(t=>[resultIdentity.symbol,resultIdentity.provider,resultIdentity.timeframe,new Date(t.entryTime).toISOString(),new Date(t.exitTime).toISOString(),t.side===1?'LONG':'SHORT',t.entry,t.exit,t.units,t.pnl,t.r,t.reason].join(','));download('NS-Backtest-'+resultIdentity.symbol+'.csv',[header,...rows].join('\n'),'text/csv');});
 $('alert-btn').addEventListener('click',()=>{$('alert-price').value=latestBar()?.close||'';renderAlerts();$('alert-dialog').showModal();});$('alert-form').addEventListener('submit',e=>{e.preventDefault();const id=identity(),value=Number($('alert-price').value);if(!Number.isFinite(value)||value<=0)return;state.alerts.unshift({id:crypto.randomUUID(),full:id.full,symbol:id.symbol,price:value,condition:$('alert-condition').value,fired:false});save();renderAlerts();toast(tr('สร้างการแจ้งเตือนแล้ว','Alert created'));});$('alert-list').addEventListener('click',e=>{const b=e.target.closest('[data-remove-alert]');if(b){state.alerts=state.alerts.filter(a=>a.id!==b.dataset.removeAlert);save();renderAlerts();}});
}

async function openBrokerTrading(){if(broker.connection&&identity().provider!=='broker'){const kind=connections.accounts.get(connections.accounts.activeId)?.kind||'all',markets=broker.catalog.filter(m=>kind==='all'||m.assetClass===kind),symbol=markets.find(m=>/^XAUUSD/i.test(m.ticker))||markets[0];if(symbol)await activateSymbol(broker.providerName+':'+symbol.ticker);}marketTools.select('trade');if($('market-panel').inert)responsive.togglePanel('watchlist');tradingUI.sync();await tradingUI.refresh();}
function clocks(){const now=new Date();for(const [id,zone,label]of[['clock-th','Asia/Bangkok','TH'],['clock-ny','America/New_York','NY']])$(id).textContent=label+' '+new Intl.DateTimeFormat('en-GB',{timeZone:zone,hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(now);if(ready&&['binance','broker'].includes(identity().provider))refreshConnection();}
async function init(){pwa=setupPWA({language:()=>state.lang,onNetwork:online=>{tradingUI?.networkChanged(online);ledgerUI?.networkChanged(online);journalDashboard?.networkChanged(online);}});document.body.classList.add('no-left');marketTools=setupMarketTabs();document.querySelector('meta[name=theme-color]').content=terminalTheme(state.theme).background;$('theme-btn').setAttribute('aria-pressed',String(state.theme==='light'));document.body.classList.toggle('light',state.theme==='light');applyLanguage();wireEvents();clocks();setInterval(clocks,1000);renderJournal();renderAlerts();renderWatchlist();connections=setupConnections({broker,tr,theme:()=>state.theme,language:()=>state.lang,onConnect:brokerConnected,onDisconnect:disconnectBroker,onSelect:symbol=>activateSymbol('broker:'+symbol),onChange:()=>{tradingUI?.sync();ledgerUI?.connectionChanged();journalDashboard?.connectionChanged();googleLogin?.render();},onTrade:openBrokerTrading});tradingUI=setupBrokerTrading({broker,connections,identity,tr,onSelect:activateSymbol,isReplay:()=>!!current()?.replay.state.active});ledgerUI=setupLedger({broker,connections,client:tradingUI.client,tr,identity,onChanged:()=>void tradingUI.refresh()});googleLogin=setupGoogleLogin({broker,connections,onLocalLogout:()=>{connections.accounts.signOut();const pending=disconnectBroker();connections.renderBroker();return pending.catch(error=>toast(error.message,true));}});journalDashboard=setupJournalDashboard({broker,connections,client:tradingUI.client,tr,onGoogleLogin:()=>googleLogin.open(),onLogout:()=>googleLogin.signOut()});responsive=setupResponsive({onChart:()=>{showTab('performance');$('analysis-panel').classList.add('collapsed');responsive?.syncAnalysis();},onMarkets:()=>connections.openGlobal(),startCollapsed:true});$('chart-container').textContent='';
 workspace=new VelaWorkspace('#chart-container',{layout:'1',layoutMode:'auto',symbol:'binance:BTCUSDT',timeframe:'15',bars:720,live:true,theme:terminalTheme(state.theme),timezone:'Asia/Bangkok',providers:{csv:()=>csv,binance:()=>binance},persist:'ns-capital-charts',storage:workspaceStorage,timeframes:['1','5','15','60','240','1D'],sync:{crosshair:true},topbar:{left:['symbol','timeframes','style','indicators','undo-redo'],right:['actions','layout','alerts','panels','screenshot']}});
 workspace.on('cell:created',()=>{for(const cell of workspace.cells())bindChart(cell.chart);});workspace.on('cell:active',()=>refreshMarket(true));workspace.on('state:changed',()=>{for(const cell of workspace.cells())bindChart(cell.chart);});for(const cell of workspace.cells())bindChart(cell.chart);
 if(workspace.cells().some(cell=>identity(cell.chart).provider==='binance'))ensureBinance();
 for(const cell of workspace.cells())if(identity(cell.chart).provider==='broker')await cell.chart.setMarket({symbol:'binance:BTCUSDT',timeframe:'15',bars:720});
 ready=true;await workspace.chart.ready();for(const cell of workspace.cells()){const chart=cell.chart;if(!chart.indicators().some(i=>i.nativeType==='ema')){for(const [length,color]of[[21,'#ef7f7f'],[50,'#e4a155'],[200,'#e5cf72']])chart.addNativeIndicator('ema',{inputs:{length,color}});}}
 refreshMarket(true);renderPaper();renderAssetCatalog();
 styleTerminalWorkspace(workspace,state.theme);
 renderWatchlist();
 const query=new URLSearchParams(location.search);if(query.get('source')==='binance'){const symbol=(query.get('symbol')||'BTCUSDT').toUpperCase();try{await activateSymbol('binance:'+binanceSymbol(symbol));}catch(error){notice(error.message);}}
 if(query.get('view')==='markets')connections.openGlobal();
 if(brokerResumeNeeded){notice(tr('เชื่อม Broker Bridge ใหม่เพื่อใช้ราคาจากบัญชีเดิม','Reconnect Broker Bridge to resume your broker charts'));connections.openBroker();}
 if(query.get('connect')==='1'&&!$('broker-dialog').open)connections.openBroker();
 if(query.get('login')==='google')googleLogin.open();
 if(query.get('ai')==='1')await connectAI();
 // Public control surface used by embedding hosts and the optional local AI adapter.
 globalThis.NSCapital={getWorkspace:()=>workspace,getConfig:()=>({...state.config}),applyConfig:config=>{state.config=validateConfig(config);updateRecipe();syncRecipeIndicators();save();},runBacktest:()=>runBacktest(),version:'1.9.0'};
}
